def merge(intervals):
    intervals = sorted(intervals)
    if not intervals:
        return []
    out=[]
    out.append(intervals[0])
    for i in range(1, len(intervals)):
        start, end = intervals[i]
        if start <= out[-1][1]:
            out[-1]=(out[-1][0], max(out[-1][1], end))
        else:
            out.append((start,end))
    return out
